    }

    /**
     * Delete reseller and reseller's cPanel accounts.
     *
     * This function deletes a reseller and all of the reseller's cPanel accounts.
     *
     * Documented: Available in cPanel & WHM 11 and later, according to the pinned operation. Permanently deletes the
     * owned cPanel accounts; deleted accounts cannot be recovered. The required terminatereseller flag controls whether
     * the main reseller account is also terminated. Use unsetupReseller to revoke reseller status while retaining
     * accounts. Returned acct entries can report individual failures despite the outer outcome; inspect each
     * result/reason. output.raw may contain HTML and private account-removal details; treat it as payload data. No
     * client retry or rollback is provided.
     *
     * API-map identity: whm1:terminatereseller#GET (wire name terminatereseller; Reseller Account Management).
     *
     * @param string $user The reseller account's username.
     * @param bool $terminatereseller Whether to terminate the reseller's main account.
     * @return TerminateResellerResult
     * @throws ApiException If transport, HTTP, the API envelope outcome, or payload validation fails.
     * @throws PayloadMismatchException If the API envelope reported success but the payload differs from the contract;
     *     the operation may already have changed state; do not retry automatically.
     * @see https://api.docs.cpanel.net/specifications/whm.openapi/reseller-account-management/resellers-terminatereseller
     */
    public function terminateReseller(string $user, bool $terminatereseller): array
    {
        /** @var TerminateResellerResult $result Validated against ResellersSpec::TERMINATERESELLER. */
        $result = ($this->run)(ResellersSpec::TERMINATERESELLER, [
            'user' => $user,
            'terminatereseller' => $terminatereseller,
        ]);

        return $result;
    }

